    id: '309', slug: 'justice-league-the-flashpoint-paradox', title: 'Justice League: The Flashpoint Paradox', title_ar: 'Justice League: The Flashpoint Paradox', year: 2013,
    director: 'Jay Oliva', director_ar: 'Jay Oliva',
    cast: ['Justin Chambers', 'C. Thomas Howell', 'Michael B. Jordan', 'Kevin McKidd', 'Dee Bradley Baker', 'Steve Blum'],
    genres: ['animation', 'action', 'scifi'],
    poster_url: 'https://image.tmdb.org/t/p/w500/hg6RYpSb3vU4i3yQDtE1YhSZNh5.jpg',
