    id: '448', slug: 'marriage-story', title: 'Marriage Story', title_ar: 'Marriage Story', year: 2019,
    director: 'Noah Baumbach', director_ar: 'Noah Baumbach',
    cast: ['Adam Driver', 'Scarlett Johansson', 'Laura Dern', 'Alan Alda', 'Ray Liotta', 'Julie Hagerty'],
    genres: ['drama'],
    poster_url: 'https://image.tmdb.org/t/p/w500/2JRyCKaRKyJAVpsIHeLvPw5nHmw.jpg',
