    id: '609', slug: 'king-richard', title: 'King Richard', title_ar: 'King Richard', year: 2021,
    director: 'Reinaldo Marcus Green', director_ar: 'Reinaldo Marcus Green',
    cast: ['Will Smith', 'Aunjanue Ellis-Taylor', 'Saniyya Sidney', 'Demi Singleton', 'Jon Bernthal', 'Mikayla LaShae Bartholomew'],
    genres: ['drama', 'history'],
    poster_url: 'https://image.tmdb.org/t/p/w500/2dfujXrxePtYJPiPHj1HkAFQvpu.jpg',
