    id: '762', slug: 'sinners', title: 'Sinners', title_ar: 'الخطاة', year: 2025,
    director: 'Ryan Coogler', director_ar: 'Ryan Coogler',
    cast: ['Michael B. Jordan', 'Hailee Steinfeld', 'Miles Caton', 'Jack O\'Connell', 'Wunmi Mosaku', 'Jayme Lawson'],
