    id: '795', slug: 'kung-fury', title: 'Kung Fury', title_ar: 'Kung Fury', year: 2015,
    director: 'David Sandberg', director_ar: 'David Sandberg',
    cast: ['David Sandberg', 'Jorma Taccone', 'Leopold Nilsson', 'Andreas Cahling', 'Helene Ahlson', 'Eos Karlsson'],
    genres: ['action', 'comedy', 'scifi'],
    poster_url: 'https://image.tmdb.org/t/p/w500/f1QpIlCqlFXp1hjnLplXb5irxip.jpg',
