    id: '934', slug: 'the-mission', title: 'The Mission', title_ar: 'The Mission', year: 1986,
    director: 'Roland Joffé', director_ar: 'Roland Joffé',
    cast: ['Robert De Niro', 'Jeremy Irons', 'Ray McAnally', 'Aidan Quinn', 'Liam Neeson', 'Cherie Lunghi'],
