    id: '982', slug: 'the-big-short', title: 'The Big Short', title_ar: 'ذا بيغ شورت', year: 2015,
    director: 'Adam McKay', director_ar: 'Adam McKay',
    cast: ['Steve Carell', 'Christian Bale', 'Ryan Gosling', 'Brad Pitt', 'Marisa Tomei', 'Melissa Leo'],
