    reviews_count: 4466, is_featured: false, release_date: '2004-05-19', tags: ['animation', 'comedy', 'family', '2004', 'vernon'],
    pros_ar: ['رسوم متحركة خلابة', 'قصة عائلية ممتعة', 'موسيقى تصويرية رائعة'],
